<?php

/* @autogenerated */
/** @psalm-suppress UnusedClosureParam */
return function (string $theme, string $title, string $innerContent, string $locale): string {
    return <<<HTML
            <!DOCTYPE html>
            <html lang="{$locale}">
            <head>
                <meta charset="UTF-8">
                <meta name="viewport" content="width=device-width, initial-scale=1.0">
                <title>{$title}</title>
                <link rel="icon" type="image/png" href="{$theme}/style/favicon.png">
                <link rel="stylesheet" href="{$theme}/style/corporate.css">
                <link rel="stylesheet" href="{$theme}/style/full.css">
                <link rel="stylesheet" href="{$theme}/style/profile.css">
            </head>
            <body class="full-window">
                <header class="app-header">
                    <div class="app-header-inner">
                        <a class="app-logo" href="/">
                            <img src="{$theme}/style/logo.png" alt="Company Logo" />
                        </a>
                    </div>
                </header>

                <main class="app-main">
                    <div class="app-content">
                        {$innerContent}
                    </div>
                </main>
            </body>
            </html>
        HTML;
};
